// Relational Database Engine Simulation inside n8n static data
const staticData = $getWorkflowStaticData('global');
// 1. DDL: Create Tables & Constraints
staticData.tables = staticData.tables || {};
staticData.tables.customers = [
{ customerId: "CUST-001", name: "Acme Corp", creditLimit: 5000.00, currentBalance: 1200.00 },
{ customerId: "CUST-002", name: "Globex Inc", creditLimit: 500.00, currentBalance: 450.00 }
];
staticData.tables.orders = [];
staticData.tables.order_items = [];
return {
json: {
status: "DATABASE_INITIALIZED",
schema: {
tables: ["customers", "orders", "order_items"],
constraints: ["FK_order_items_orders", "CHECK_credit_limit"],
indexes: ["idx_orders_customer", "idx_items_order"]
},
timestamp: new Date().toISOString()
}
};

return [
{
json: {
orderId: "ORD-DB-5001",
customerId: "CUST-101",
orderDate: new Date().toISOString(),
lineItems: [
{ sku: "SKU-SRV-01", description: "Cloud Managed Server", quantity: 2, unitPrice: 450.00 },
{ sku: "SKU-LIC-02", description: "Enterprise Security Seat", quantity: 5, unitPrice: 75.00 }
]
}
}
];

const staticData = $getWorkflowStaticData('global');
staticData.orders = staticData.orders || [];
const order = $input.item.json;
const totalAmount = (order.lineItems || []).reduce((acc, it) => acc + (it.quantity * it.unitPrice), 0);
const orderRecord = {
orderId: order.orderId,
customerId: order.customerId,
orderDate: order.orderDate,
totalAmount: totalAmount,
status: "PENDING"
};
staticData.orders.push(orderRecord);
return {
json: {
...order,
headerInserted: true,
totalAmount: totalAmount
}
};

const staticData = $getWorkflowStaticData('global');
staticData.orderItems = staticData.orderItems || [];
const order = $input.item.json;
const lineItems = order.lineItems || [];
const insertedItems = lineItems.map((it, idx) => {
const record = {
itemId: `ITEM-${order.orderId}-${idx + 1}`,
orderId: order.orderId,
sku: it.sku,
description: it.description,
quantity: it.quantity,
unitPrice: it.unitPrice,
lineTotal: Number((it.quantity * it.unitPrice).toFixed(2))
};
staticData.orderItems.push(record);
return record;
});
return {
json: {
orderId: order.orderId,
customerId: order.customerId,
totalAmount: order.totalAmount,
itemsCount: insertedItems.length,
items: insertedItems
}
};

const staticData = $getWorkflowStaticData('global');

staticData.customers = staticData.customers || [
  {
    customerId: "CUST-101",
    name: "Apex Global",
    balance: 5000,
    creditLimit: 10000
  }
];

staticData.orders = staticData.orders || [];
staticData.orderItems = staticData.orderItems || [];

// Get incoming order
const order = $input.item.json;

// Find customer
const customer = staticData.customers.find(
  c => c.customerId === order.customerId
);

// Customer not found
if (!customer) {

  // Remove pending parent order
  staticData.orders = staticData.orders.filter(
    o => o.orderId !== order.orderId
  );

  // Remove child order items
  staticData.orderItems = staticData.orderItems.filter(
    i => i.orderId !== order.orderId
  );

  return {
    json: {
      transactionStatus: "ROLLED_BACK",
      reason: "CUSTOMER_NOT_FOUND",
      orderId: order.orderId,
      customerId: order.customerId
    }
  };
}

// Calculate projected balance
const newBalance = Number(
  (customer.currentBalance + order.totalAmount).toFixed(2)
);

// Check credit limit
if (newBalance > customer.creditLimit) {

  // Rollback parent order
  staticData.orders = staticData.orders.filter(
    o => o.orderId !== order.orderId
  );

  // Rollback child order items
  staticData.orderItems = staticData.orderItems.filter(
    i => i.orderId !== order.orderId
  );

  return {
    json: {
      transactionStatus: "ROLLED_BACK",
      reason: "CREDIT_LIMIT_EXCEEDED",
      orderId: order.orderId,
      customerId: customer.customerId,
      currentBalance: customer.currentBalance,
      creditLimit: customer.creditLimit,
      attemptedCharge: order.totalAmount,
      projectedBalance: newBalance
    }
  };
}

// Commit transaction
customer.currentBalance = newBalance;

// Update order status
const committedOrder = staticData.orders.find(
  o => o.orderId === order.orderId
);

if (committedOrder) {
  committedOrder.status = "COMMITTED";
}

return {
  json: {
    transactionStatus: "COMMITTED",
    orderId: order.orderId,
    customerId: customer.customerId,
    updatedBalance: newBalance,
    creditLimit: customer.creditLimit,
    committedAt: new Date().toISOString()
  }
};

const staticData = $getWorkflowStaticData('global');

const orderId = $json.orderId;

// Find the order
const order = (staticData.orders || []).find(
  o => o.orderId === orderId
);

// Check whether the order exists
if (!order) {
  return {
    json: {
      status: "ERROR",
      message: "Order not found in database",
      orderId: orderId
    }
  };
}

// Find the related customer
const customer = (staticData.customers || []).find(
  c => c.customerId === order.customerId
);

// Find related order items
const items = (staticData.orderItems || []).filter(
  i => i.orderId === orderId
);

// Check whether the customer exists
if (!customer) {
  return {
    json: {
      status: "ERROR",
      message: "Customer not found in database",
      orderId: orderId,
      customerId: order.customerId
    }
  };
}

// Return consolidated order details (JOIN result)
return {
  json: {
    orderId: order.orderId,
    status: order.status,
    customer: {
      id: customer.customerId,
      name: customer.name,
      currentBalance: customer.currentBalance
    },
    orderDate: order.orderDate,
    totalAmount: order.totalAmount,
    lineItems: items
  }
};

const item = $input.item.json;

// Safely get line items
const lineItems = Array.isArray(item.lineItems)
  ? item.lineItems
  : [];

// Return final transaction audit
return {
  json: {
    auditEvent: "ACID_TRANSACTION_COMMITTED",
    auditStatus: "DATABASE_TRANSACTION_VERIFIED",
    orderId: item.orderId,
    customerId: item.customer?.id,
    customerName: item.customer?.name,
    transactionStatus: item.status,
    persistedTotal: item.totalAmount,
    lineItemCount: lineItems.length,
    customerBalance: item.customer?.currentBalance,
    auditTimestamp: new Date().toISOString()
  }
};
